import assert from 'node:assert/strict';
import { createTenant, issueInput, useTemporaryDatabase } from './tests/server/_support/fixtures.ts';
import { emit, onHandlerError } from './src/lib/event-bus.ts';
import { toIsoTimestamp } from './src/types/common.ts';
import * as issues from './src/server/services/issue-service.ts';
import * as comments from './src/server/services/comment-service.ts';
import * as projects from './src/server/services/project-service.ts';
import * as search from './src/server/services/search-service.ts';
import * as searchRepo from './src/server/repositories/search-repository.ts';
import * as issueRepo from './src/server/repositories/issue-repository.ts';
import * as commentRepo from './src/server/repositories/comment-repository.ts';
import * as projectRepo from './src/server/repositories/project-repository.ts';
import * as orgRepo from './src/server/repositories/organization-repository.ts';
import { runSearchReindexJob } from './src/server/jobs/search-reindex-job.ts';

const cleanup = await useTemporaryDatabase();
const detach = search.registerSearchListeners();
const errors = [];
const offErrors = onHandlerError((type, error) => errors.push({ type, error }));
try {
  const starter = await createTenant('literal-check', 'starter');
  const ent = await createTenant('syntax-check', 'enterprise');
  const growth = await createTenant('plan-check', 'growth');
  const query = (tenant, q, extra = {}) => search.search(tenant.actors.member, {
    orgId: tenant.org.id, q, kinds: ['issue', 'comment', 'project'], limit: 100, ...extra,
  });
  const starterIssue = await issues.createIssue(starter.actors.member,
    issueInput(starter.org.id, starter.project.id, { title: 'Release 2: hotfix 100% snake_case C:\\\\folder "'! done'"' }));
  await issues.createIssue(starter.actors.member,
    issueInput(starter.org.id, starter.project.id, { title: 'Release 20 hotfix 1000 snake case C:folder done' }));
  for (const q of ['Release 2: hotfix', '100%', 'snake_case', '\\\\', '"'!'"']) {
    const page = await query(starter, q);
    assert.equal(page.total, 1, q);
    assert.equal(page.items[0].id, starterIssue.id, q);
  }
  const issue = await issues.createIssue(ent.actors.member,
    issueInput(ent.org.id, ent.project.id, { title: 'flaky deploy issue' }));
  const comment = await comments.createComment(ent.actors.member, {
    orgId: ent.org.id, issueId: issue.id, body: 'flaky deploy comment', parentId: null, mentionedUserIds: [],
  });
  for (const q of ['kind:comment flaky', 'in:comments flaky', 'kind:comments project:' + ent.project.id + ' flaky']) {
    const page = await query(ent, q, { kinds: ['issue'], projectId: starter.project.id });
    if (q.includes('project:')) {
      assert.equal(page.total, 1, q);
      assert.equal(page.items[0].id, comment.id, q);
    } else {
      assert.equal(page.total, 0, 'caller project filter still applies');
      const unscoped = await query(ent, q, { kinds: ['issue'] });
      assert.equal(unscoped.total, 1, q);
      assert.equal(unscoped.items[0].id, comment.id, q);
    }
  }
  const scoped = await query(ent, 'project:' + ent.project.id + ' deploy');
  assert.equal(scoped.total, 2);
  const combined = await query(ent, 'kind:issue kind:comment unknown:value kind: flaky', { kinds: ['project'] });
  assert.equal(combined.total, 2);
  await comments.updateComment(ent.actors.member, { orgId: ent.org.id, commentId: comment.id, body: 'edited scoped comment' });
  assert.equal((await query(ent, 'edited', { kinds: ['comment'], projectId: ent.project.id })).total, 1);
  assert.equal((await query(ent, 'flaky', { kinds: ['comment'] })).total, 0);
  await projects.updateProject(ent.actors.member, { orgId: ent.org.id, projectId: ent.project.id, name: 'Renamed searchable project' });
  assert.equal((await query(ent, 'Renamed', { kinds: ['project'] })).total, 1);
  for (const [kind, item, needle] of [['comment', comment, 'edited'], ['project', ent.project, 'Renamed']]) {
    await searchRepo.deleteSearchDocument(ent.org.id, kind, item.id);
    await emit('search.reindex_requested', { orgId: ent.org.id, actorId: null,
      occurredAt: toIsoTimestamp(new Date()), subjectKind: kind, subjectId: item.id });
    assert.equal((await query(ent, needle, { kinds: [kind], projectId: ent.project.id })).total, 1);
  }
  await searchRepo.deleteSearchDocument(ent.org.id, 'comment', comment.id);
  const rebuilt = await runSearchReindexJob(ent.org.id);
  assert.equal(rebuilt.failed, 0);
  assert.equal((await query(ent, 'edited', { kinds: ['comment'], projectId: ent.project.id })).total, 1);
  const growthIssue = await issues.createIssue(growth.actors.member,
    issueInput(growth.org.id, growth.project.id, { title: 'shared marker' }));
  await comments.createComment(growth.actors.member, { orgId: growth.org.id,
    issueId: growthIssue.id, body: 'shared marker', parentId: null, mentionedUserIds: [] });
  for (const kinds of [[], ['comment'], ['issue', 'comment', 'project']]) {
    const page = await query(growth, 'shared marker', { kinds });
    assert.equal(page.total, 1);
    assert.equal(page.items[0].kind, 'issue');
  }
  await orgRepo.updateOrg(growth.org.id, { orgId: growth.org.id, settings: { enabledFlagOverrides: ['advanced_search'] } });
  assert.equal((await query(growth, 'kind:comment shared')).total, 1);
  for (const [kind, item, repo, archive] of [
    ['issue', issue, issueRepo, 'archiveIssue'],
    ['comment', comment, commentRepo, 'archiveComment'],
    ['project', ent.project, projectRepo, 'archiveProject'],
  ]) {
    await repo[archive](ent.org.id, item.id);
    await emit('search.reindex_requested', { orgId: ent.org.id, actorId: null,
      occurredAt: toIsoTimestamp(new Date()), subjectKind: kind, subjectId: item.id });
    assert.equal((await searchRepo.searchDocuments({ orgId: ent.org.id, q: '', kinds: [kind], limit: 100 })).total, 0);
  }
  for (const kind of ['issue', 'comment', 'project']) {
    await searchRepo.upsertSearchDocument(ent.org.id, kind, 'missing-subject', 'stale content', ent.project.id);
    await emit('search.reindex_requested', { orgId: ent.org.id, actorId: null,
      occurredAt: toIsoTimestamp(new Date()), subjectKind: kind, subjectId: 'missing-subject' });
    assert.equal((await searchRepo.searchDocuments({ orgId: ent.org.id, q: 'stale content', kinds: [kind], limit: 100 })).total, 0);
  }
  assert.deepEqual(errors, []);
  console.log('Search behavior checks passed.');
} finally {
  offErrors();
  detach();
  cleanup();
}
TS"

