/bin/zsh -lc "TMPDIR=/tmp node --import tsx --input-type=module <<'TS'
import assert from 'node:assert/strict';
import { createTenant, issueInput, useTemporaryDatabase } from './tests/server/_support/fixtures.ts';
import * as issueRepo from './src/server/repositories/issue-repository.ts';
import * as commentRepo from './src/server/repositories/comment-repository.ts';
import * as projectRepo from './src/server/repositories/project-repository.ts';
import * as searchRepo from './src/server/repositories/search-repository.ts';
import { runSearchReindexJob } from './src/server/jobs/search-reindex-job.ts';
const cleanup = await useTemporaryDatabase();
try {
  const tenant = await createTenant('rebuild-pages', 'enterprise');
  let firstIssue;
  for (let i = 0; i < 101; i++) {
    await projectRepo.insertProject({ ...tenant.project, slug: 'project-' + i, name: 'project ' + i, key: 'P' + i });
    const issue = await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id), tenant.actors.member.userId, i + 1);
    firstIssue ??= issue;
    await commentRepo.insertComment({ orgId: tenant.org.id, issueId: firstIssue.id,
      body: 'paged scoped comment ' + i, parentId: null, mentionedUserIds: [] }, tenant.actors.member.userId);
  }
  const result = await runSearchReindexJob(tenant.org.id);
  assert.equal(result.failed, 0);
  assert.equal(result.processed, 304);
  assert.equal(await searchRepo.countIndexed(tenant.org.id), 304);
  const scoped = await searchRepo.searchDocuments({ orgId: tenant.org.id, q: 'paged scoped',
    kinds: ['comment'], projectId: tenant.project.id, limit: 100 });
  assert.equal(scoped.total, 101);
  assert.equal(scoped.items.length, 100);
  assert.ok(scoped.nextCursor);
  const next = await searchRepo.searchDocuments({ orgId: tenant.org.id, q: 'paged scoped',
    kinds: ['comment'], projectId: tenant.project.id, limit: 100, cursor: scoped.nextCursor });
  assert.equal(next.total, 101);
  assert.equal(next.items.length, 1);
  console.log('Rebuild and result pagination checks passed.');
} finally { cleanup(); }
TS"
